extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var SaveManagerScript = load("res://core/save_manager.gd")
	if not check("script_loads", SaveManagerScript != null, "Lo script res://core/save_manager.gd deve caricarsi correttamente"):
		return

	var path_json: String = SaveManagerScript.get_slot_json_path(1)
	check("path_json", path_json == "user://save_slot_01.json", "get_slot_json_path(1) deve restituire user://save_slot_01.json (ha restituito %s)" % path_json)

	var path_img: String = SaveManagerScript.get_slot_image_path(1)
	check("path_img", path_img == "user://save_slot_01.png", "get_slot_image_path(1) deve restituire user://save_slot_01.png (ha restituito %s)" % path_img)

	var save_manager = SaveManagerScript.new()
	var tree = Engine.get_main_loop() as SceneTree
	if tree and tree.root:
		tree.root.add_child(save_manager)
		await wait_frames(2)
		var result: bool = await save_manager.save_game(1, "Capitolo Test", {"line": 2})
		check("save_result", result == true, "save_game deve restituire true")
		check("json_exists", FileAccess.file_exists("user://save_slot_01.json"), "Il file user://save_slot_01.json deve essere stato creato")
		check("png_exists", FileAccess.file_exists("user://save_slot_01.png"), "Il file user://save_slot_01.png deve essere stato creato")

		if FileAccess.file_exists("user://save_slot_01.json"):
			var file := FileAccess.open("user://save_slot_01.json", FileAccess.READ)
			var content := file.get_as_text()
			var data: Variant = JSON.parse_string(content)
			if check("data_dict", data is Dictionary, "Il contenuto del file salvato deve essere un Dictionary JSON"):
				check("chapter_title", String(data.get("chapter_title", "")) == "Capitolo Test", "La chiave chapter_title deve corrispondere a 'Capitolo Test'")
				check("version", int(data.get("version", 0)) == 1, "La chiave version deve valere 1")
				check("timestamp", not String(data.get("timestamp", "")).is_empty(), "La chiave timestamp deve essere presente e non vuota")
		save_manager.queue_free()

