func _run_tests() -> void:
	var SaveManagerScript = load("res://core/save_manager.gd")
	if not check("save_mgr", SaveManagerScript != null, "SaveManager deve esistere"):
		return

	var sm = SaveManagerScript.new()
	var tree = Engine.get_main_loop() as SceneTree
	if tree and tree.root:
		tree.root.add_child(sm)
		await wait_frames(2)
		await sm.save_game(3, "Capitolo Eliminazione", {})
		sm.queue_free()

	var screen := await instantiate_scene("res://ui/save_load_screen.tscn")
	if not check("screen_valid", screen != null, "La scena res://ui/save_load_screen.tscn deve istanziarsi"):
		return

	var slot_3 = screen.get_node_or_null("SlotGrid/Slot_03")
	if check("slot3_exists", slot_3 != null, "Lo slot Slot_03 deve esistere in SlotGrid"):
		var lbl = slot_3.get_node_or_null("ChapterLabel") as Label
		check("chapter_loaded", lbl != null and lbl.text == "Capitolo Eliminazione", "ChapterLabel in Slot_03 deve mostrare 'Capitolo Eliminazione' (mostra '%s')" % (lbl.text if lbl else ""))

	if has_function(screen, "request_delete_slot"):
		screen.request_delete_slot(3)
		var dialog = screen.get_node_or_null("ConfirmDialog") as ConfirmationDialog
		check("dialog_visible", dialog != null and dialog.visible, "La finestra ConfirmDialog deve essere mostrata dopo request_delete_slot(3)")

		call_if_exists(screen, "_on_confirm_dialog_confirmed")
		await wait_frames(2)

		check("json_deleted", not FileAccess.file_exists("user://save_slot_03.json"), "Il file JSON dello slot 3 deve essere stato eliminato dal disco")
		check("png_deleted", not FileAccess.file_exists("user://save_slot_03.png"), "Il file PNG dello slot 3 deve essere stato eliminato dal disco")

		if slot_3:
			var lbl = slot_3.get_node_or_null("ChapterLabel") as Label
			check("slot3_reset", lbl != null and lbl.text == "Vuoto", "Dopo l'eliminazione Slot_03 deve mostrare 'Vuoto' in ChapterLabel")

